import { getConnection } from '../connection';
import type { ActivityExecution } from '../types';

export async function create(data: Omit<ActivityExecution, 'id'>): Promise<ActivityExecution> {
  try {
    const db = await getConnection();
    const result = await db.create('activity_execution', data);
    return result[0];
  } catch (error) {
    throw new Error(`Failed to create activity execution: ${error.message}`);
  }
}

export async function read(id: string): Promise<ActivityExecution | null> {
  try {
    const db = await getConnection();
    const result = await db.select(`activity_execution:${id}`);
    return result || null;
  } catch (error) {
    throw new Error(`Failed to read activity execution: ${error.message}`);
  }
}

export async function update(id: string, data: Partial<ActivityExecution>): Promise<ActivityExecution> {
  try {
    const db = await getConnection();
    const result = await db.update(`activity_execution:${id}`, data);
    return result;
  } catch (error) {
    throw new Error(`Failed to update activity execution: ${error.message}`);
  }
}

export async function remove(id: string): Promise<void> {
  try {
    const db = await getConnection();
    await db.delete(`activity_execution:${id}`);
  } catch (error) {
    throw new Error(`Failed to delete activity execution: ${error.message}`);
  }
}

export async function list(limit = 100): Promise<ActivityExecution[]> {
  try {
    const db = await getConnection();
    const result = await db.query('SELECT * FROM activity_execution ORDER BY started_at DESC LIMIT $limit', { limit });
    return result[0] || [];
  } catch (error) {
    throw new Error(`Failed to list activity executions: ${error.message}`);
  }
}
```

