Implement transaction wrapper with automatic rollback:
```typescript
import { getConnection } from './connection';

export async function withTransaction<T>(
  operations: (db: any) => Promise<T>
): Promise<T> {
  const db = await getConnection();

  try {
    // Start transaction
    await db.query('BEGIN TRANSACTION');

    // Execute operations
    const result = await operations(db);

    // Commit if successful
    await db.query('COMMIT TRANSACTION');

    return result;
  } catch (error) {
    // Rollback on error
    try {
      await db.query('CANCEL TRANSACTION');
    } catch (rollbackError) {
      throw new Error(`Transaction rollback failed: ${rollbackError.message}. Original error: ${error.message}`);
    }
    throw new Error(`Transaction failed: ${error.message}`);
  }
}
```

**File 2: {{projectPath}}/{{clientDirectory}}/queries.ts**

Implement utility functions for common queries:

```typescript
import { getConnection } from './connection';
import type { TemplateMetrics, FailurePattern, ActivityExecution } from './types';

export async function getLatestMetrics(templateId: string): Promise<TemplateMetrics | null> {
  try {
    const db = await getConnection();
    const result = await db.query(
      'SELECT * FROM template_metrics WHERE template_id = $templateId ORDER BY last_updated DESC LIMIT 1',
      { templateId }
    );
    return result[0]?.[0] || null;
  } catch (error) {
    throw new Error(`Failed to get latest metrics: ${error.message}`);
  }
}

export async function getFailurePatterns(
  templateId: string,
  limit = 10
): Promise<FailurePattern[]> {
  try {
    const db = await getConnection();
    const result = await db.query(
      'SELECT * FROM failure_pattern WHERE template_id = $templateId ORDER BY frequency DESC LIMIT $limit',
      { templateId, limit }
    );
    return result[0] || [];
  } catch (error) {
    throw new Error(`Failed to get failure patterns: ${error.message}`);
  }
}

export async function getExecutionHistory(
  templateId: string,
  timeRange?: { start: Date; end: Date }
): Promise<ActivityExecution[]> {
  try {
    const db = await getConnection();
    let query = 'SELECT * FROM activity_execution WHERE template_id = $templateId';
    const params: any = { templateId };

    if (timeRange) {
      query += ' AND started_at >= $start AND started_at <= $end';
      params.start = timeRange.start;
      params.end = timeRange.end;
    }

    query += ' ORDER BY started_at DESC';

    const result = await db.query(query, params);
    return result[0] || [];
  } catch (error) {
    throw new Error(`Failed to get execution history: ${error.message}`);
  }
}

export async function getSuccessRateTrend(
  templateId: string,
  timeRange: { start: Date; end: Date }
): Promise<{ date: string; success_rate: number }[]> {
  try {
    const db = await getConnection();
    const result = await db.query(
      `SELECT 
        time::floor(started_at, 1d) as date,
        (count(IF status = 'completed') / count(*) * 100) as success_rate
      FROM activity_execution 
      WHERE template_id = $templateId 
        AND started_at >= $start 
        AND started_at <= $end
      GROUP BY date
      ORDER BY date`,
      { templateId, start: timeRange.start, end: timeRange.end }
    );
    return result[0] || [];
  } catch (error) {
    throw new Error(`Failed to get success rate trend: ${error.message}`);
  }
}

export async function findSimilarFailures(
  errorPattern: string,
  limit = 5
): Promise<FailurePattern[]> {
  try {
    const db = await getConnection();
    const result = await db.query(
      'SELECT * FROM failure_pattern WHERE error_pattern ~~ $pattern ORDER BY frequency DESC LIMIT $limit',
      { pattern: `%${errorPattern}%`, limit }
    );
    return result[0] || [];
  } catch (error) {
    throw new Error(`Failed to find similar failures: ${error.message}`);
  }
}
```

